create table public.sales_settings(organization_id uuid primary key references public.organizations(id) on delete cascade,credit_limit_policy text not null default 'BLOCK' check(credit_limit_policy in('BLOCK','ALLOW_WITH_APPROVAL')),backorder_policy text not null default 'ALLOW' check(backorder_policy in('ALLOW','DISALLOW')),minimum_price_policy text not null default 'BLOCK' check(minimum_price_policy in('BLOCK','ALLOW_WITH_APPROVAL')),updated_at timestamptz not null default now(),updated_by uuid references auth.users(id));
create table public.customers(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,customer_code text not null,customer_type text not null check(customer_type in('INDIVIDUAL','BUSINESS')),display_name text not null,legal_name text,first_name text,last_name text,email text,phone text,alternate_phone text,tax_number text,registration_number text,default_currency text not null check(default_currency~'^[A-Z]{3}$'),default_price_list_id uuid,default_payment_terms text,credit_limit numeric(20,4) not null default 0 check(credit_limit>=0),credit_status text not null default 'NORMAL' check(credit_status in('NORMAL','ON_HOLD','BLOCKED')),sales_rep_id uuid references auth.users(id),notes text,status text not null default 'ACTIVE' check(status in('ACTIVE','INACTIVE','BLOCKED','ARCHIVED')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid not null references auth.users(id),unique(organization_id,id),unique(organization_id,customer_code),foreign key(organization_id,default_price_list_id) references public.price_lists(organization_id,id));
