create table public.customer_addresses(id uuid primary key default gen_random_uuid(),organization_id uuid not null,customer_id uuid not null,address_type text not null check(address_type in('BILLING','DELIVERY','OFFICE','HOME','OTHER')),line_1 text not null,line_2 text,city text,state_region text,postal_code text,country_code text not null,is_default_billing boolean not null default false,is_default_delivery boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,id),foreign key(organization_id,customer_id) references public.customers(organization_id,id) on delete cascade);
