create table public.sales_order_lines(id uuid primary key default gen_random_uuid(),organization_id uuid not null,sales_order_id uuid not null,product_variant_id uuid not null,packaging_id uuid not null,description_snapshot text not null,sku_snapshot text not null,ordered_quantity numeric(24,6) not null,conversion_snapshot numeric(24,8) not null,ordered_base_quantity numeric(24,6) not null,unit_price numeric(24,8) not null,discount numeric(20,4) not null default 0,tax numeric(20,4) not null default 0,line_total numeric(20,4) not null,reserved_base_quantity numeric(24,6) not null default 0,fulfilled_base_quantity numeric(24,6) not null default 0,cancelled_base_quantity numeric(24,6) not null default 0,backordered_base_quantity numeric(24,6) not null default 0,reservation_id uuid,unique(organization_id,id),foreign key(organization_id,sales_order_id) references public.sales_orders(organization_id,id) on delete cascade,foreign key(organization_id,product_variant_id) references public.product_variants(organization_id,id),foreign key(organization_id,packaging_id) references public.product_variant_packaging(organization_id,id),foreign key(organization_id,reservation_id) references public.inventory_reservations(organization_id,id));
