create table public.sales_fulfillment_lines(id uuid primary key default gen_random_uuid(),organization_id uuid not null,fulfilment_id uuid not null,sales_order_line_id uuid not null,product_variant_id uuid not null,packaging_id uuid not null,entered_quantity numeric(24,6) not null,conversion_snapshot numeric(24,8) not null,base_quantity numeric(24,6) not null,revenue_base numeric(28,8) not null,inventory_cost_base numeric(28,8) not null default 0,gross_margin_base numeric(28,8) not null default 0,unique(organization_id,id),foreign key(organization_id,fulfilment_id) references public.sales_fulfillments(organization_id,id) on delete cascade,foreign key(organization_id,sales_order_line_id) references public.sales_order_lines(organization_id,id),foreign key(organization_id,product_variant_id) references public.product_variants(organization_id,id),foreign key(organization_id,packaging_id) references public.product_variant_packaging(organization_id,id));
