create table public.customer_invoice_lines(id uuid primary key default gen_random_uuid(),organization_id uuid not null,invoice_id uuid not null,sales_order_line_id uuid,sales_fulfillment_line_id uuid,product_variant_id uuid,description_snapshot text not null,sku_snapshot text,quantity numeric(24,6) not null check(quantity>0),unit_price numeric(24,8) not null check(unit_price>=0),discount numeric(20,4) not null default 0,tax numeric(20,4) not null default 0,line_total numeric(20,4) not null,unique(organization_id,id),foreign key(organization_id,invoice_id) references public.customer_invoices(organization_id,id) on delete cascade,foreign key(organization_id,sales_order_line_id) references public.sales_order_lines(organization_id,id),foreign key(organization_id,sales_fulfillment_line_id) references public.sales_fulfillment_lines(organization_id,id),foreign key(organization_id,product_variant_id) references public.product_variants(organization_id,id));
create table public.customer_invoice_fulfillments(organization_id uuid not null,invoice_id uuid not null,fulfilment_id uuid not null,primary key(invoice_id,fulfilment_id),foreign key(organization_id,invoice_id) references public.customer_invoices(organization_id,id) on delete cascade,foreign key(organization_id,fulfilment_id) references public.sales_fulfillments(organization_id,id));
create table public.sales_return_reasons(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,code text not null,name text not null,is_active boolean not null default true,requires_notes boolean not null default false,created_by uuid not null references auth.users(id),unique(organization_id,id),unique(organization_id,code));
create table public.sales_returns(id uuid primary key default gen_random_uuid(),organization_id uuid not null,business_id uuid not null,return_number text not null,customer_id uuid not null,sales_order_id uuid,sales_fulfilment_id uuid,customer_invoice_id uuid,branch_id uuid not null,return_date timestamptz not null,reason_id uuid not null,status text not null default 'REQUESTED' check(status in('REQUESTED','APPROVED','RECEIVED','INSPECTED','POSTED','REJECTED','CANCELLED')),notes text,idempotency_key uuid not null,inventory_transaction_id uuid,credit_note_id uuid,created_by uuid not null references auth.users(id),posted_at timestamptz,created_at timestamptz not null default now(),unique(organization_id,id),unique(organization_id,return_number),unique(organization_id,idempotency_key),foreign key(organization_id,business_id) references public.businesses(organization_id,id),foreign key(organization_id,customer_id) references public.customers(organization_id,id),foreign key(organization_id,sales_order_id) references public.sales_orders(organization_id,id),foreign key(organization_id,sales_fulfilment_id) references public.sales_fulfillments(organization_id,id),foreign key(organization_id,customer_invoice_id) references public.customer_invoices(organization_id,id),foreign key(organization_id,branch_id) references public.branches(organization_id,id),foreign key(organization_id,reason_id) references public.sales_return_reasons(organization_id,id),foreign key(organization_id,inventory_transaction_id) references public.inventory_transactions(organization_id,id));
create table public.sales_return_lines(id uuid primary key default gen_random_uuid(),organization_id uuid not null,sales_return_id uuid not null,sales_fulfillment_line_id uuid not null,product_variant_id uuid not null,packaging_id uuid not null,requested_quantity numeric(24,6) not null,received_quantity numeric(24,6) not null default 0,accepted_quantity numeric(24,6) not null default 0,rejected_quantity numeric(24,6) not null default 0,conversion_snapshot numeric(24,8) not null,accepted_base_quantity numeric(24,6) not null default 0,condition text,disposition text check(disposition in('RESTOCK_NORMAL','RESTOCK_DAMAGED','REJECT_RETURN','SCRAP')),destination_location_id uuid,return_unit_cost_base numeric(24,8),notes text,unique(organization_id,id),foreign key(organization_id,sales_return_id) references public.sales_returns(organization_id,id) on delete cascade,foreign key(organization_id,sales_fulfillment_line_id) references public.sales_fulfillment_lines(organization_id,id),foreign key(organization_id,product_variant_id) references public.product_variants(organization_id,id),foreign key(organization_id,packaging_id) references public.product_variant_packaging(organization_id,id),foreign key(organization_id,destination_location_id) references public.storage_locations(organization_id,id),check(accepted_quantity+rejected_quantity<=received_quantity));
create table public.customer_credit_notes(id uuid primary key default gen_random_uuid(),organization_id uuid not null,credit_note_number text not null,customer_id uuid not null,customer_invoice_id uuid,sales_return_id uuid,branch_id uuid not null,credit_date date not null,currency text not null,exchange_rate numeric(24,10) not null check(exchange_rate>0),subtotal numeric(20,4) not null,tax numeric(20,4) not null default 0,total numeric(20,4) not null,base_currency_total numeric(20,4) not null,reason text not null,status text not null default 'DRAFT' check(status in('DRAFT','APPROVED','ISSUED','VOID')),refund_disposition text not null default 'CUSTOMER_CREDIT' check(refund_disposition in('CUSTOMER_CREDIT','REFUND_PENDING')),idempotency_key uuid not null,created_by uuid not null references auth.users(id),approved_by uuid references auth.users(id),approved_at timestamptz,created_at timestamptz not null default now(),unique(organization_id,id),unique(organization_id,credit_note_number),unique(organization_id,idempotency_key),foreign key(organization_id,customer_id) references public.customers(organization_id,id),foreign key(organization_id,customer_invoice_id) references public.customer_invoices(organization_id,id),foreign key(organization_id,sales_return_id) references public.sales_returns(organization_id,id),foreign key(organization_id,branch_id) references public.branches(organization_id,id));
alter table public.sales_returns add constraint sales_returns_credit_note_fk foreign key(organization_id,credit_note_id) references public.customer_credit_notes(organization_id,id);
create table public.sales_activity(id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id) on delete cascade,document_type text not null,document_id uuid not null,action text not null,actor_id uuid references auth.users(id),details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index customers_search_idx on public.customers(organization_id,status,display_name,customer_code);create index sales_quotes_status_idx on public.sales_quotations(organization_id,branch_id,status,expiry_date);create index sales_orders_queue_idx on public.sales_orders(organization_id,branch_id,status,requested_delivery_date);create index sales_order_lines_open_idx on public.sales_order_lines(organization_id,sales_order_id,product_variant_id) where fulfilled_base_quantity+cancelled_base_quantity<ordered_base_quantity;create index sales_fulfillments_order_idx on public.sales_fulfillments(organization_id,sales_order_id,fulfilled_at desc);create index customer_invoices_due_idx on public.customer_invoices(organization_id,branch_id,customer_id,status,due_date);create index sales_returns_customer_idx on public.sales_returns(organization_id,customer_id,status,return_date desc);create index sales_activity_document_idx on public.sales_activity(organization_id,document_type,document_id,created_at desc);
create view public.customer_receivables with(security_invoker=true) as select i.organization_id,i.customer_id,sum(case when i.status not in('DRAFT','VOID') then i.base_currency_total-i.credit_note_total_base-i.amount_paid_base else 0 end) outstanding_base,sum(case when i.status not in('DRAFT','VOID') and i.due_date<current_date then i.base_currency_total-i.credit_note_total_base-i.amount_paid_base else 0 end) overdue_base,min(i.due_date) filter(where i.status not in('DRAFT','VOID') and i.base_currency_total>i.credit_note_total_base+i.amount_paid_base) oldest_due_date from public.customer_invoices i group by i.organization_id,i.customer_id;

-- Transactional projections and immutable costing links used by the Sales RPC layer.
alter table public.sales_quotations add column idempotency_key uuid, add column request_hash text;
alter table public.sales_orders add column request_hash text, add column confirmed_at timestamptz, add column cancelled_at timestamptz, add column credit_override_by uuid references auth.users(id);
alter table public.sales_fulfillments add column request_hash text not null;
alter table public.sales_fulfillment_lines add column inventory_movement_id uuid, add column gross_profit_base numeric(28,8) not null default 0;
alter table public.customer_invoices add column request_hash text not null;
alter table public.customer_invoice_lines add column conversion_snapshot numeric(24,8) not null check(conversion_snapshot>0);
alter table public.sales_returns add column request_hash text not null;
alter table public.customer_credit_notes add column request_hash text not null, add column issued_at timestamptz, add column issued_by uuid references auth.users(id);

create unique index sales_quotations_idempotency_idx on public.sales_quotations(organization_id,idempotency_key) where idempotency_key is not null;
create unique index sales_orders_quotation_once_idx on public.sales_orders(organization_id,originating_quotation_id) where originating_quotation_id is not null;
create unique index sales_credit_return_once_idx on public.customer_credit_notes(organization_id,sales_return_id) where sales_return_id is not null and status<>'VOID';
create index sales_order_backorders_idx on public.sales_order_lines(organization_id,product_variant_id) where backordered_base_quantity>0;

alter table public.sales_order_lines add constraint sales_order_line_quantities_check check(
  ordered_quantity>0 and conversion_snapshot>0 and ordered_base_quantity>0 and unit_price>=0
  and reserved_base_quantity>=0 and fulfilled_base_quantity>=0 and cancelled_base_quantity>=0 and backordered_base_quantity>=0
  and fulfilled_base_quantity+cancelled_base_quantity<=ordered_base_quantity
  and reserved_base_quantity<=ordered_base_quantity-fulfilled_base_quantity-cancelled_base_quantity
);
alter table public.sales_fulfillment_lines add constraint sales_fulfillment_line_quantities_check check(entered_quantity>0 and conversion_snapshot>0 and base_quantity>0);
alter table public.sales_fulfillment_lines add constraint sales_fulfillment_line_movement_fk foreign key(organization_id,inventory_movement_id) references public.inventory_movements(organization_id,id);
alter table public.sales_fulfillment_lines add constraint sales_fulfillment_line_once unique(fulfilment_id,sales_order_line_id);
alter table public.sales_return_lines add constraint sales_return_line_quantities_check check(requested_quantity>0 and received_quantity>=0 and accepted_quantity>=0 and rejected_quantity>=0 and accepted_base_quantity>=0 and conversion_snapshot>0);

alter table public.inventory_cost_allocations add constraint inventory_cost_allocations_org_id_key unique(organization_id,id);
create table public.sales_return_cost_allocations(
 id uuid primary key default gen_random_uuid(), organization_id uuid not null, sales_return_line_id uuid not null,
 original_cost_allocation_id uuid, quantity_base numeric(24,6) not null check(quantity_base>0), unit_cost_base numeric(24,8) not null check(unit_cost_base>=0),
 created_at timestamptz not null default now(), unique(organization_id,id),
 foreign key(organization_id,sales_return_line_id) references public.sales_return_lines(organization_id,id) on delete cascade,
 foreign key(organization_id,original_cost_allocation_id) references public.inventory_cost_allocations(organization_id,id)
);

create view public.customer_credit_exposure with(security_invoker=true) as
select c.organization_id,c.id customer_id,
 coalesce(r.outstanding_base,0) outstanding_receivables_base,
 coalesce(sum(case when o.status in('CONFIRMED','PARTIALLY_RESERVED','RESERVED','PARTIALLY_FULFILLED')
  then greatest(o.base_currency_total-coalesce(inv.invoiced_base,0),0) else 0 end),0) confirmed_commitments_base,
 coalesce(r.outstanding_base,0)+coalesce(sum(case when o.status in('CONFIRMED','PARTIALLY_RESERVED','RESERVED','PARTIALLY_FULFILLED')
  then greatest(o.base_currency_total-coalesce(inv.invoiced_base,0),0) else 0 end),0) exposure_base
from public.customers c
left join public.customer_receivables r on r.organization_id=c.organization_id and r.customer_id=c.id
left join public.sales_orders o on o.organization_id=c.organization_id and o.customer_id=c.id
left join lateral(select sum(i.base_currency_total) invoiced_base from public.customer_invoices i where i.organization_id=o.organization_id and i.sales_order_id=o.id and i.status not in('DRAFT','VOID')) inv on true
group by c.organization_id,c.id,r.outstanding_base;
